import{_ as e,o as d,c as a,ae as o}from"./chunks/framework.C4zpkcTP.js";const h=JSON.parse('{"title":"PaymentCallback & Status","description":"Property reference for PaymentCallback, PaymentStatusResult and the PaymentStatus enum.","frontmatter":{"title":"PaymentCallback & Status","description":"Property reference for PaymentCallback, PaymentStatusResult and the PaymentStatus enum."},"headers":[],"relativePath":"laravel-myanmar-payments/references/payment-callback.md","filePath":"laravel-myanmar-payments/references/payment-callback.md"}'),c={name:"laravel-myanmar-payments/references/payment-callback.md"};function r(s,t,n,l,u,y){return d(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="paymentcallback-status" tabindex="-1">PaymentCallback &amp; Status <a class="header-anchor" href="#paymentcallback-status" aria-label="Permalink to &quot;PaymentCallback &amp; Status&quot;">​</a></h1><h2 id="paymentcallback" tabindex="-1">PaymentCallback <a class="header-anchor" href="#paymentcallback" aria-label="Permalink to &quot;PaymentCallback&quot;">​</a></h2><p>Returned by every gateway&#39;s <code>handleCallback()</code> and by <code>ayaPay()-&gt;verifyRedirect()</code>, after the signature has been verified.</p><table tabindex="0"><thead><tr><th>Property / Method</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>orderId</code></td><td><code>string</code></td><td>Your order id</td></tr><tr><td><code>status</code></td><td><code>PaymentStatus</code></td><td>The status mapped onto this package&#39;s statuses</td></tr><tr><td><code>gatewayStatus</code></td><td><code>string</code></td><td>The gateway&#39;s own status value, unmapped</td></tr><tr><td><code>gatewayReference</code></td><td><code>?string</code></td><td>The gateway&#39;s id for the payment</td></tr><tr><td><code>amount</code></td><td><code>?string</code></td><td>The amount as the gateway sent it</td></tr><tr><td><code>raw</code></td><td><code>array</code></td><td>The verified payload; JSON numbers are their exact text as <code>string</code>s</td></tr><tr><td><code>isSuccessful()</code></td><td><code>bool</code></td><td><code>status === PaymentStatus::Successful</code></td></tr><tr><td><code>acknowledgement</code></td><td><code>Acknowledgement</code></td><td>The response the gateway expects (<code>status</code>, <code>body</code>, <code>headers</code>)</td></tr></tbody></table><p>In Laravel, return <code>MyanmarPayments::acknowledge($callback)</code> to send the acknowledgement.</p><p>Returned by <code>MyanmarPayments::handleCallback($gateway, $request)</code> too, for a gateway chosen by name.</p><h2 id="paymentstatusresult" tabindex="-1">PaymentStatusResult <a class="header-anchor" href="#paymentstatusresult" aria-label="Permalink to &quot;PaymentStatusResult&quot;">​</a></h2><p>Returned by <code>kbzPay()-&gt;status()</code>, <code>ayaPay()-&gt;status()</code> and <code>yomaMmqr()-&gt;status()</code>.</p><table tabindex="0"><thead><tr><th>Property / Method</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>orderId</code></td><td><code>?string</code></td><td>Your order id. <code>null</code> for Yoma MMQR, which only returns the reference</td></tr><tr><td><code>status</code></td><td><code>PaymentStatus</code></td><td>The mapped status</td></tr><tr><td><code>gatewayStatus</code></td><td><code>string</code></td><td>The gateway&#39;s own status value</td></tr><tr><td><code>gatewayReference</code></td><td><code>?string</code></td><td>The gateway&#39;s id for the payment</td></tr><tr><td><code>amount</code></td><td><code>?string</code></td><td>The amount as the gateway reported it</td></tr><tr><td><code>raw</code></td><td><code>array</code></td><td>The gateway&#39;s response</td></tr><tr><td><code>isSuccessful()</code></td><td><code>bool</code></td><td><code>status === PaymentStatus::Successful</code></td></tr></tbody></table><h2 id="paymentstatus" tabindex="-1">PaymentStatus <a class="header-anchor" href="#paymentstatus" aria-label="Permalink to &quot;PaymentStatus&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Case</th><th>Value</th><th><code>isFinal()</code></th></tr></thead><tbody><tr><td><code>PaymentStatus::Successful</code></td><td><code>successful</code></td><td><code>true</code></td></tr><tr><td><code>PaymentStatus::Pending</code></td><td><code>pending</code></td><td><code>false</code></td></tr><tr><td><code>PaymentStatus::Failed</code></td><td><code>failed</code></td><td><code>true</code></td></tr><tr><td><code>PaymentStatus::Canceled</code></td><td><code>canceled</code></td><td><code>true</code></td></tr><tr><td><code>PaymentStatus::Expired</code></td><td><code>expired</code></td><td><code>true</code></td></tr><tr><td><code>PaymentStatus::Unknown</code></td><td><code>unknown</code></td><td><code>false</code></td></tr></tbody></table><p><code>PaymentStatus::cases()</code> lists every status.</p>',12)])])}const i=e(c,[["render",r]]);export{h as __pageData,i as default};
